UPDATE questions SET data_json = '{"options":[{"id":"o1","text":"Reference evapotranspiration × crop coefficient"},{"id":"o2","text":"Rainfall − irrigation"},{"id":"o3","text":"Soil moisture × yield"},{"id":"o4","text":"NDVI × temperature"}]}', answer_json = '{"correct":["o1"]}', explanation = 'Reference evapotranspiration (ET₀) is calculated from weather data for a standard reference crop; the crop coefficient (Kc) adjusts it for the actual crop and its growth stage, so ETc = ET₀ × Kc. The other options combine quantities that do not describe crop water use.', updated_at = '2026-10-27T00:00:00.000Z' WHERE id = 'q_a1m3_3' AND NOT EXISTS (SELECT 1 FROM courses WHERE id = 'crs_a1' AND published_at IS NOT NULL);
