UPDATE questions SET data_json = '{"options":[{"id":"o1","text":"Management zones"},{"id":"o2","text":"Validation sets"},{"id":"o3","text":"Crop coefficients"},{"id":"o4","text":"Market signals"}]}', answer_json = '{"correct":["o1"]}', explanation = 'Management zones group parts of a field that behave alike, such as a low area that stays wet or a sandy ridge that dries first, so seeding, nitrogen and irrigation can be matched to each zone instead of treating the whole field as uniform.', updated_at = '2026-10-27T00:00:00.000Z' WHERE id = 'q_a1m3_5' AND NOT EXISTS (SELECT 1 FROM courses WHERE id = 'crs_a1' AND published_at IS NOT NULL);
