UPDATE questions SET data_json = '{"options":[{"id":"o1","text":"The least access needed, such as read-only"},{"id":"o2","text":"Full control of every setting"},{"id":"o3","text":"Access to all of your farm records"},{"id":"o4","text":"Permanent access that cannot be revoked"}]}', answer_json = '{"correct":["o1"]}', explanation = 'Grant the least access the job needs. A connector that only reads irrigation data does not need to change settings, see your other records or keep access forever, and the less access it holds, the less harm it can do if it is misused or compromised. Review connected services regularly.', updated_at = '2026-10-27T00:00:00.000Z' WHERE id = 'q_a1x_e6' AND NOT EXISTS (SELECT 1 FROM courses WHERE id = 'crs_a1' AND published_at IS NOT NULL);
